{"template": "A bag has {red} red and {blue} blue balls. Two balls are drawn without replacement. What is the probability that both are red?", "parameters": [{"name": "red", "minimum": "2", "maximum": "9", "step": "1", "original": "3"}, {"name": "blue", "minimum": "2", "maximum": "9", "step": "1", "original": "5"}], "solver": "from fractions import Fraction
def solve(params):
    r, b = params["red"], params["blue"]
    first = Fraction(r, r + b)
    both = first * Fraction(r - 1, r + b - 1)
    return {"answer": both, "steps": {"first_red": first, "both_red": both}}
", "step_names": ["first_red", "both_red"]}
